import csv
import io
import re
from typing import List, Dict, Any, Optional

def parse_csv(raw_csv: str):
    if raw_csv is None:
        return {"columns": [], "rows": []}

    text = raw_csv.replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")

    def split_fields(line: str) -> List[str]:
        return next(csv.reader([line], delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False))

    def is_data_row(line: str) -> bool:
        s = line.strip()
        if not s:
            return False
        try:
            fields = split_fields(line)
        except Exception:
            return False
        if len(fields) < 2:
            return False
        first = fields[0].strip()
        return bool(re.match(r"^\d{1,2}/\d{1,2}/\d{4}$", first))

    start_idx = 0
    for i, line in enumerate(lines):
        if is_data_row(line):
            start_idx = i
            break

    data_text = "\n".join(lines[start_idx:]).strip("\n")
    if not data_text.strip():
        return {"columns": [], "rows": []}

    try:
        rows = list(csv.reader(io.StringIO(data_text), delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False))
    except Exception:
        rows = []
        current = []
        buf = []
        in_quotes = False
        for ch in data_text:
            buf.append(ch)
            if ch == '"':
                if in_quotes:
                    nxt = None
                    if len(buf) >= 2 and buf[-2] == '"':
                        pass
                    else:
                        in_quotes = False
                else:
                    in_quotes = True
            if ch == "\n" and not in_quotes:
                line = "".join(buf[:-1])
                buf = []
                try:
                    parsed = next(csv.reader([line], delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False))
                except Exception:
                    parsed = [line]
                rows.append(parsed)
        if buf:
            try:
                parsed = next(csv.reader(["".join(buf)], delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False))
            except Exception:
                parsed = ["".join(buf)]
            rows.append(parsed)

    if not rows:
        return {"columns": [], "rows": []}

    header = rows[0]
    data_rows = rows[1:]

    max_width = max([len(header)] + [len(r) for r in data_rows]) if data_rows else len(header)
    if len(header) < max_width:
        header = header + [""] * (max_width - len(header))

    normalized_rows = []
    for r in data_rows:
        if len(r) < max_width:
            r = r + [""] * (max_width - len(r))
        elif len(r) > max_width:
            r = r[:max_width - 1] + [",".join(r[max_width - 1:])]
        normalized_rows.append([str(v) for v in r])

    return {"columns": [str(v) for v in header], "rows": normalized_rows}
